<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { ArrowLeft, ArrowRight, BookOpen, Check, Dices, LoaderCircle } from '@lucide/vue'
import type { TrpgCompletionReport, TrpgCompletionPerson } from '@/api/types'
import { completionDice, completionOutcomes } from './trpgCompletionState'

const props = defineProps<{ report: TrpgCompletionReport | null; loading: boolean; busy: boolean; failed: boolean; skipDisabled: boolean; error: string }>()
const emit = defineEmits<{ retry: []; skip: []; tools: []; reload: []; archive: []; transcript: []; back: [] }>()
const page = ref(0)
const selectedPerson = ref<number | null>(null)
const container = ref<HTMLElement | null>(null)
const heading = ref<HTMLElement | null>(null)
const sections = ['序章', '共同旅程', '调查员们', '掷骰回顾']
const dice = computed(() => completionDice(props.report?.rolls || [], selectedPerson.value))
const team = computed(() => completionDice(props.report?.rolls || [], null))
const date = computed(() => props.report?.completedAt?.slice(0, 10).replaceAll('-', '.') || '')
watch(() => props.report?.title, () => { page.value = 0; selectedPerson.value = null })
function state(person: TrpgCompletionPerson) {
  if (person.dead) return '已逝'
  const states = [person.dying && '濒死', person.unconscious && '昏迷', person.majorWound && '重伤', person.temporaryInsanity && '临时疯狂'].filter(Boolean)
  return states.length ? states.join(' · ') : '存活'
}
function name(id: number) { return props.report?.investigators.find((person) => person.characterId === id)?.name || '调查员' }
function outcomeLabel(value: string) { return completionOutcomes.find((item) => item.value === value)?.label || value }
async function move(delta: number) {
  page.value = Math.max(0, Math.min(3, page.value + delta))
  await nextTick()
  container.value?.scrollTo({ top: 0, behavior: 'instant' })
  container.value?.scrollIntoView({ block: 'start', behavior: 'instant' })
  heading.value?.focus({ preventScroll: true })
}
</script>

<template>
  <main ref="container" class="completion-stage">
    <header class="completion-top"><button class="text-button" @click="emit('back')"><ArrowLeft :size="14" />返回当前世界</button><span>跑团完成记录</span><button class="text-button" :disabled="busy" @click="emit('tools')">跑团工具</button><button class="text-button" @click="emit('transcript')">查看对话</button></header>
    <div v-if="loading || report?.status !== 'ready'" class="completion-wait" aria-live="polite">
      <LoaderCircle v-if="loading || busy" :size="34" class="spin" /><BookOpen v-else :size="34" />
      <small>THE STORY CONTINUES IN MEMORY</small>
      <h1>{{ loading ? '正在读取完成记录' : failed ? '总结尚未完成' : busy ? '正在整理这段共同旅程' : '正篇落幕，故事留在你们之间' }}</h1>
      <p>{{ error || (failed ? '重新生成将再次整理人物后传与完成报告，全部完成后归档。' : busy ? '正在生成人物后传与完成报告，完成后即可翻阅。' : '为你和同伴留下共同旅程、人物后传与掷骰回顾。') }}</p>
      <button v-if="!loading && report" class="button primary" :disabled="busy" @click="emit('retry')"><LoaderCircle v-if="busy" class="spin" :size="16" />{{ busy ? '正在生成' : failed ? '重新生成总结' : '生成跑团总结并归档' }}</button>
      <button v-if="!loading && report" class="button ghost" :disabled="busy || skipDisabled" @click="emit('skip')">直接结束跑团</button><p v-if="!loading && !busy && report" class="completion-footnote">直接结束将保留现有记录，跳过人物后传与完成报告。</p><button v-if="!loading && !report" class="button ghost" @click="emit('reload')">重新读取</button>
    </div>
    <template v-else-if="report">
      <nav class="completion-progress" aria-label="完成记录进度"><span v-for="(label, index) in sections" :key="label" :class="{ current: index === page, done: index < page }" :aria-current="index === page ? 'step' : undefined"><i><Check v-if="index < page" :size="12" /><template v-else>{{ index === 0 ? '序' : `0${index}` }}</template></i>{{ label }}</span></nav>
      <div class="completion-book">
        <h1 ref="heading" class="sr-only" tabindex="-1">{{ sections[page] }}</h1>
        <section v-show="page === 0" class="completion-opening">
          <div class="completion-cover" :class="{ illustrated: report.coverUrl }">
            <img v-if="report.coverUrl" :src="report.coverUrl" alt="" />
            <div class="completion-cover-copy"><small>CALL OF CTHULHU · 跑团记录</small><span class="completion-sigil">✦</span><h2>{{ report.title }}</h2><span>{{ date }}</span><strong>已完成</strong></div>
          </div>
          <div class="completion-opening-copy"><small class="completion-kicker">你们一起，走到了故事的最后。</small><h2>这一段旅程，<br />有你，也有同伴。</h2><p class="completion-prose">{{ report.ending }}</p><div class="completion-team"><span v-for="person in report.investigators" :key="person.characterId">{{ person.name }}<small v-if="person.dead"> · 已逝</small></span></div><div class="completion-totals"><div><strong>{{ report.investigators.length }}</strong><span>位调查员同行</span></div><div><strong>{{ report.turnCount }}</strong><span>轮共同经历</span></div><div><strong>{{ team.total }}</strong><span>次公开检定</span></div></div><p class="completion-footnote">{{ date }} · {{ report.archivedAt ? '已归档，可随时重读' : '完成记录已保存' }}</p></div>
        </section>
        <section v-show="page === 1">
          <div class="completion-section-heading"><small class="completion-kicker">01 / OUR JOURNEY</small><h2>我们曾一同走过</h2><p>从第一次调查，到故事落幕。这里留下了你们共同经历的片段。</p></div>
          <div class="completion-journey"><article v-for="(chapter, index) in report.journey" :key="index"><span class="completion-chapter-number">{{ String(index + 1).padStart(2, '0') }}</span><div><h3>{{ chapter.title }}</h3><p class="completion-prose">{{ chapter.excerpt }}</p><details><summary>阅读这一段的完整摘要</summary><p class="completion-full-text">{{ chapter.summary }}</p></details></div></article></div>
          <p v-if="!report.journey.length" class="completion-empty">这次旅程没有可节选的场景摘要。你们的结局与后传仍保存在这份记录里。</p>
        </section>
        <section v-show="page === 2">
          <div class="completion-section-heading"><small class="completion-kicker">02 / THE INVESTIGATORS</small><h2>故事之后的我们</h2><p>有些人带着变化继续生活，有些人被同伴记住。每个人都在这场旅程里留下了痕迹。</p></div>
          <div class="completion-people"><article v-for="person in report.investigators" :key="person.characterId" :class="{ dead: person.dead }"><header><div class="completion-avatar"><img v-if="person.image" :src="person.image" alt="" /><span v-else>{{ person.name.slice(0, 1) }}</span></div><div><h3>{{ person.name }}<small v-if="person.player">你的调查员</small></h3><p>{{ person.occupation || '调查员' }}</p></div><span class="completion-person-state">{{ state(person) }}</span></header><div class="completion-resources"><div><small>生命 HP</small><p><template v-if="person.initialHp != null"><del>{{ person.initialHp }}</del><span>→</span></template><strong>{{ person.hp ?? '—' }}</strong></p></div><div><small>理智 SAN</small><p><template v-if="person.initialSan != null"><del>{{ person.initialSan }}</del><span>→</span></template><strong>{{ person.san ?? '—' }}</strong></p></div></div><small class="completion-kicker">后来</small><p class="completion-prose">{{ person.lead }}</p><details><summary>展开人物后传</summary><p class="completion-full-text">{{ person.epilogue }}</p></details></article></div>
        </section>
        <section v-show="page === 3">
          <div class="completion-section-heading"><small class="completion-kicker">03 / THE DICE REMEMBER</small><h2>那些屏住呼吸的瞬间</h2><p>每一次掷骰，都曾让你们等待一个答案。</p></div>
          <div class="completion-dice"><div class="completion-filters" role="group" aria-label="检定统计对象"><button :aria-pressed="selectedPerson == null" @click="selectedPerson = null">全体调查员</button><button v-for="person in report.investigators" :key="person.characterId" :aria-pressed="selectedPerson === person.characterId" @click="selectedPerson = person.characterId">{{ person.name }}</button></div><div class="completion-dice-title"><Dices :size="23" /><strong>{{ dice.total }}</strong><span>次公开检定</span></div><div class="completion-bar" role="img" :aria-label="dice.counts.map((item) => `${item.label}${item.count}次`).join('，')"><span v-for="item in dice.counts" :key="item.value" :style="{ width: `${dice.total ? item.count / dice.total * 100 : 0}%`, background: item.color }" /></div><div class="completion-counts"><div v-for="item in dice.counts" :key="item.value"><span><i :style="{ background: item.color }" />{{ item.label }}</span><strong>{{ item.count }}</strong></div></div><p class="completion-footnote">统计已公开并完成结算的调查员检定。大成功、成功、失败、大失败分别计数。</p>
          <div class="completion-highlights"><h3>骰子记住了这些时刻</h3><p v-if="!dice.total" class="completion-empty">还没有可统计的公开检定。</p><p v-else-if="!dice.highlights.length" class="completion-empty">这次没有大成功或大失败。平常的点数，也一步步写成了你们的故事。</p><article v-for="(roll, index) in dice.highlights" :key="index"><span class="completion-roll-value">{{ roll.value == null ? '—' : String(roll.value).padStart(2, '0') }}</span><div><strong>{{ name(roll.characterId) }} · {{ roll.checkName || '检定' }}</strong><small>{{ roll.turnNo > 0 ? `第 ${roll.turnNo} 轮 · ` : '' }}{{ roll.target != null ? `目标值 ${roll.target}` : '公开记录' }}</small></div><span :class="{ fumble: roll.outcome === 'FUMBLE' }">{{ outcomeLabel(roll.outcome) }}</span></article></div></div>
        </section>
      </div>
      <footer class="completion-navigation"><button class="button ghost" :disabled="page === 0 || busy" @click="move(-1)"><ArrowLeft :size="16" />上一页</button><span>{{ page + 1 }} / 4</span><button v-if="page < 3" class="button primary" @click="move(1)">继续<ArrowRight :size="16" /></button><button v-else class="button primary" :disabled="busy" @click="emit('archive')"><LoaderCircle v-if="busy" class="spin" :size="16" />返回档案</button></footer>
      <p v-if="error" role="alert" class="completion-error">{{ error }}</p>
    </template>
  </main>
</template>

<style scoped>
.completion-stage{height:100vh;overflow:auto;color:var(--ink);background:var(--paper);padding:24px 36px 32px;font-size:14px;line-height:1.7}.completion-top{display:flex;justify-content:space-between;align-items:center;gap:12px;font-size:12px;color:var(--muted);max-width:1060px;margin:auto}.completion-top button{display:flex;align-items:center;gap:7px}.completion-progress{display:flex;justify-content:center;gap:40px;margin:36px auto;color:var(--muted);font-size:12px}.completion-progress>span{display:flex;align-items:center;gap:9px}.completion-progress i{font:normal 12px Georgia;display:grid;place-items:center;width:25px;height:25px;border:1px solid var(--line);border-radius:50%}.completion-progress .current{color:var(--pine);font-weight:600}.completion-progress .current i,.completion-progress .done i{color:var(--surface);border-color:var(--pine);background:var(--pine)}.completion-book,.completion-navigation{max-width:960px;margin:auto}.completion-book{min-height:540px}.completion-stage h2,.completion-stage h3,.completion-stage p{margin:0}.completion-stage h2{font:400 30px/1.5 'Songti SC',STSong,serif;letter-spacing:.04em}.completion-kicker{color:var(--pine);font-size:11px;letter-spacing:.08em}.completion-opening{display:grid;grid-template-columns:270px minmax(0,1fr);gap:54px;align-items:center;padding:32px 0 42px}.completion-cover{position:relative;min-height:392px;border-radius:4px 10px 10px 4px;background:var(--pine);color:#f7efdd;box-shadow:7px 10px 25px #213f3522,inset 8px 0 0 #0002;overflow:hidden}.completion-cover>img{position:absolute;width:100%;height:100%;object-fit:cover;opacity:.28}.completion-cover-copy{position:relative;min-height:392px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:26px;gap:22px}.completion-cover small{font-size:9px;letter-spacing:.1em}.completion-cover h2{font-size:30px;overflow-wrap:anywhere}.completion-sigil{font-size:38px;font-weight:200}.completion-cover-copy>span:last-of-type{font:12px Georgia;letter-spacing:.14em}.completion-cover strong{border:1px solid #f7efdd66;padding:2px 18px;font-size:11px;font-weight:400;letter-spacing:.18em}.completion-opening-copy h2{margin:12px 0 22px;font-size:32px}.completion-prose{white-space:pre-wrap;font:15px/2 'Songti SC',STSong,serif;overflow-wrap:anywhere}.completion-team{display:flex;gap:8px 18px;flex-wrap:wrap;margin:23px 0;font-size:12px}.completion-team small{color:var(--muted)}.completion-totals{border-top:1px solid var(--line);padding-top:20px;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.completion-totals strong{display:block;font:32px Georgia;color:var(--pine)}.completion-totals span{display:block;color:var(--muted);font-size:11px;margin-top:7px}.completion-footnote{font-size:11px;color:var(--muted);margin-top:20px!important}.completion-section-heading{padding:12px 0 30px}.completion-section-heading h2{margin:7px 0 12px}.completion-section-heading p{color:var(--muted);font-size:13px}.completion-journey article{display:grid;grid-template-columns:42px minmax(0,1fr);gap:20px;padding:24px 0;border-top:1px solid var(--line)}.completion-chapter-number{font:26px Georgia;color:var(--pine);opacity:.65}.completion-stage h3{font-size:16px;font-weight:500}.completion-journey h3{margin-bottom:8px}.completion-stage details{font-size:12px;margin-top:15px}.completion-stage summary{cursor:pointer;color:var(--pine);width:fit-content;padding:4px 0}.completion-full-text{white-space:pre-wrap;overflow-wrap:anywhere;color:var(--muted);font-size:13px;line-height:1.9;margin-top:12px!important;border-top:1px solid var(--line);padding-top:14px}.completion-people{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.completion-people article{padding:23px;border:1px solid var(--line);background:var(--surface);border-radius:8px}.completion-people header{display:grid;grid-template-columns:42px minmax(0,1fr) auto;gap:12px;align-items:center}.completion-avatar{width:42px;height:48px;border:1px solid var(--line);border-radius:4px;display:grid;place-items:center;background:var(--pine-soft);font:23px 'Songti SC',serif;overflow:hidden}.completion-avatar img{width:100%;height:100%;object-fit:cover}.completion-people h3 small{display:inline-block;color:var(--pine);font-size:9px;background:var(--pine-soft);padding:1px 4px;margin-left:7px}.completion-people header p{color:var(--muted);font-size:11px}.completion-person-state{font-size:11px;color:var(--pine);max-width:80px;text-align:right}.dead .completion-person-state{color:var(--wine)}.completion-resources{display:grid;grid-template-columns:1fr 1fr;gap:12px;border-block:1px solid var(--line);padding:13px 0;margin:20px 0}.completion-resources small{color:var(--muted);font-size:11px}.completion-resources p{display:flex;align-items:center;gap:12px;margin-top:4px}.completion-resources del{font:17px Georgia;color:var(--muted);text-decoration:none}.completion-resources p>span{color:var(--muted)}.completion-resources strong{font:23px Georgia}.completion-dice{border:1px solid var(--line);border-radius:8px;background:var(--surface);padding:26px}.completion-filters{display:flex;flex-wrap:wrap;gap:8px}.completion-filters button{padding:5px 12px;border:1px solid var(--line);border-radius:5px;background:transparent;cursor:pointer;font-size:12px}.completion-filters button[aria-pressed=true]{background:var(--pine);color:var(--surface);border-color:var(--pine)}.completion-dice-title{display:flex;align-items:baseline;gap:12px;margin:27px 0 17px;color:var(--pine)}.completion-dice-title strong{font:38px Georgia}.completion-dice-title>span{font-size:12px;color:var(--muted)}.completion-bar{height:15px;display:flex;overflow:hidden;border-radius:4px;background:var(--line)}.completion-counts{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:21px}.completion-counts span{font-size:11px;color:var(--muted);display:flex;gap:6px;align-items:center}.completion-counts i{width:7px;height:7px;border-radius:50%}.completio